// The world outside Brazil: events from every continent, from the end of the last ice age to the 1990s.
// Same format as the thread (history.js), which merges all of this into its own lists. This file does not import history.js.
// Several cases come from The Dawn of Everything (Graeber and Wengrow): cities without kings, assemblies, refusals of power.
// Where the reading is debated, the text says so.

/* ---------- events ---------- */
export const WORLD_EVENTS = [
  /* foragers and first gardens (to 6000 BC) */
  { id: 'gobeklitepe', y: -9500, y2: -8000, k: 'peoples', place: 'Göbekli Tepe, Anatolia', p: [38.92, 37.22], t: 'Göbekli Tepe',
    txt: 'On a hilltop in what is now southeastern Turkey, people who did not yet farm raised circles of stone pillars up to 5 meters tall around 9500 BC. The pillars are carved with foxes, snakes and vultures. For a long time the site was read as a sanctuary where hunter-gatherers met for feasts. More recent digs found houses, cisterns and many grinding stones, and scholars now debate whether people already lived there all year. Either way, the monument came before farming, not after it.', src: ['schmidt', 'graeber'] },
  { id: 'fertilewheat', y: -9000, y2: -6500, k: 'peoples', place: 'Fertile Crescent', p: [40.0, 36.4], t: 'The first wheat fields',
    txt: 'In the Fertile Crescent, from the Jordan valley to the upper Euphrates, wheat, barley, lentils, goats and sheep were domesticated between about 9500 and 6500 BC. The process took some 3,000 years. Villages planted a little, gathered wild plants, hunted and fished, and the ears of grain changed slowly. Graeber and Wengrow speak of "play farming" to say that no one had to choose once and for all between planting and foraging. The idea of a quick "agricultural revolution" that changed everything at once does not fit this evidence.', src: ['fuller', 'graeber'] },
  { id: 'catalhoyuk', y: -7100, y2: -5950, k: 'peoples', place: 'Çatalhöyük, Anatolia', p: [32.83, 37.67], t: 'Çatalhöyük',
    txt: 'For more than a thousand years, between about 7100 and 6000 BC, thousands of people lived at Çatalhöyük, on the Anatolian plateau. Their mud-brick houses were packed against each other with no streets: you entered through the roof. There is no palace, no central temple and no house much bigger than the rest. Bones and teeth show that men and women ate the same food and did similar work. The townspeople farmed and kept animals, but they still hunted and gathered a great deal.', src: ['hodder', 'graeber'] },
  { id: 'yangtzerice', y: -7000, y2: -4000, k: 'peoples', place: 'Lower Yangtze, China', p: [121.0, 30.0], t: 'Yangtze rice',
    txt: 'In the Yangtze valley, in southern China, villages were already harvesting wild rice more than 9,000 years ago. Domestication was slow. At Tianluoshan, near the river mouth, the share of domesticated rice in the harvests was still growing around 4500 BC, alongside acorns, water chestnuts and fish. In northern China, in the Yellow River valley, millet was domesticated at about the same time.', src: ['fuller'] },
  { id: 'balsasmaize', y: -6700, k: 'peoples', place: 'Balsas River valley, Mexico', p: [-100.5, 18.2], t: 'Maize is domesticated',
    txt: 'In the Balsas River basin, in southwestern Mexico, people who lived by hunting and gathering began to grow teosinte, a grass with tiny ears, about 8,700 years ago. It took thousands of years of selection to produce maize with large ears. Squash was already grown in Mexico before that; beans came later, and the three ended up planted together. From Mexico, maize spread across the Americas and, after 1492, around the world.', src: ['piperno'] },

  /* from villages to the first cities (6000 BC to 0) */
  { id: 'taliankimega', y: -4100, y2: -3400, k: 'peoples', place: 'Talianki, Ukraine', p: [30.5, 48.8], t: 'The Trypillia mega-sites',
    txt: 'Between about 4100 and 3400 BC, on the black soils of what is now Ukraine, settlements of the Cucuteni-Trypillia culture grew to more than 200 hectares. They had over a thousand houses laid out in rings around a large empty space. Talianki and Nebelivka were among the largest settlements in the world at the time. There is no sign of a palace, central temple, state storehouse or wall; instead there were meeting houses spread through the neighborhoods. Graeber and Wengrow take them as cities without rulers, but whether they were lived in all year, and by how many people, is still debated.', src: ['chapman', 'graeber'] },
  { id: 'urukwriting', y: -3300, y2: -3000, k: 'ideas', place: 'Uruk, Mesopotamia', p: [45.64, 31.32], t: 'Uruk and writing',
    txt: 'Uruk, in southern Mesopotamia, had tens of thousands of inhabitants around 3300 BC. The oldest clay tablets with writing come from there. They were first used to count barley, beer, sheep and temple workers. Who ruled the city is debated. There are images of an important male figure, whom archaeologists call the "priest-king", and later texts speak of assemblies of elders and citizens who decided things together.', src: ['vandemieroop', 'graeber'] },
  { id: 'caralnortechico', y: -2600, y2: -1800, k: 'peoples', place: 'Caral, Peru', p: [-77.52, -10.89], t: 'Caral and the cities of Norte Chico',
    txt: 'In the Supe River valley, near the coast of Peru, Caral already had stone pyramids, sunken circular plazas and residential quarters around 2600 BC, the time of Egypt’s pyramids. It is the oldest known city in the Americas. There are almost no weapons, walls or bodies with signs of violence. Food came from anchovy fishing on the coast and from irrigated fields of cotton, squash and beans, traded between the valleys.', src: ['shady'] },
  { id: 'mohenjodaro', y: -2600, y2: -1900, k: 'peoples', place: 'Mohenjo-daro, Indus Valley', p: [68.14, 27.33], t: 'The Indus cities, without palaces',
    txt: 'Mohenjo-daro and Harappa, in the Indus River valley, had straight streets and bricks of the same proportions across hundreds of kilometers. Almost every house had a well, a bathroom and covered drains. Archaeologists found no palaces, royal tombs or statues of rulers; one of the best-known public buildings is a large tank, perhaps for ritual bathing. The Indus script has not been deciphered, and no one knows who governed. Some think of city councils, others of priests.', src: ['kenoyer', 'graeber'] },
  { id: 'pyramids', y: -2560, k: 'government', place: 'Giza, Egypt', p: [31.13, 29.98], t: 'The pyramids of Giza',
    txt: 'Around 2560 BC, the pharaoh Khufu had the largest of the pyramids built at Giza, with more than 2 million blocks and 146 meters tall. It was not built by slaves, as people used to say. Nearby, archaeologists found workers’ villages, bakeries, breweries and laborers’ tombs, some with bones treated by doctors. Egypt had already been a unified kingdom for some 500 years, with a king seen as a god, scribes and taxes paid in grain. It is one of the first states in the full sense of the word.', src: ['lehner'] },
  { id: 'knossos', y: -1900, y2: -1450, k: 'peoples', place: 'Knossos, Crete', p: [25.16, 35.3], t: 'Minoan Crete',
    txt: 'On Crete, from about 1900 BC, large complexes such as Knossos brought together storerooms, workshops, ceremonial courts and painted rooms. Archaeologists call them palaces, but kings hardly appear in Minoan paintings and figurines. At the center of the scenes are women, often priestesses. Graeber and Wengrow argue that power on Crete may have been in women’s hands; other scholars think the evidence does not allow that claim. Around 1450 BC, the palaces were destroyed or taken over by Mycenaean Greeks.', src: ['shelmerdine', 'graeber'] },
  { id: 'hammurabi', y: -1754, k: 'government', place: 'Babylon', p: [44.42, 32.54], t: 'The Code of Hammurabi',
    txt: 'Around 1754 BC, Hammurabi, king of Babylon, had about 280 laws carved on a stone stela. Penalties changed with the person: injuring a noble cost more than injuring a commoner or an enslaved person. The code also set wages, prices and interest, and in its opening the king says he rules so that "the strong may not oppress the weak". The stela was found in 1901 at Susa, in Iran, and is now in the Louvre.', src: ['vandemieroop'] },
  { id: 'romanrepublic', y: -509, y2: -27, k: 'government', place: 'Rome', p: [12.48, 41.89], t: 'Rome: from republic to empire',
    txt: 'According to tradition, in 509 BC the Romans drove out their last king. From then on they were governed by two consuls elected each year, a Senate of aristocrats and assemblies of citizens. In three centuries Rome conquered Italy and the Mediterranean, and the labor of millions of enslaved people sustained its estates and cities. Civil wars ended the republic: in 27 BC, Octavian received the title Augustus and became the first emperor. Latin and Roman law lie at the root of Portuguese and of Brazil’s laws.', src: ['beard'] },
  { id: 'athens', y: -508, k: 'ideas', place: 'Athens', p: [23.72, 37.97], t: 'Athenian democracy',
    txt: 'In 508 BC, Cleisthenes reorganized the citizens of Athens and gave the assembly the power to decide laws, wars and spending. Any citizen could speak there, and many offices were filled by lot. But a citizen meant only an adult man born of Athenian parents. Women, foreigners and enslaved people, perhaps a quarter of the population, were left out. The word democracy, "power of the people", comes from there.', src: ['cartledge'] },
  { id: 'alexander', y: -334, y2: -323, k: 'conflict', place: 'Gaugamela', p: [43.45, 36.57], t: 'Alexander conquers the Persian Empire',
    txt: 'In 334 BC, Alexander, king of Macedon, crossed into Asia with about 40,000 soldiers. In 331 BC he defeated the Persian king Darius III at Gaugamela, in what is now northern Iraq, and within a few years he reached the Indus Valley. He died in Babylon in 323 BC, aged 32, and his generals divided the empire. Cities he founded, such as Alexandria in Egypt, spread the Greek language as far as Central Asia.', src: ['lanefox'] },
  { id: 'hansilkroad', y: -138, y2: 220, k: 'economy', place: 'Dunhuang, Gansu corridor', p: [94.66, 40.14], t: 'The Han and the Silk Road',
    txt: 'Around 138 BC, Emperor Wu of the Han dynasty sent the envoy Zhang Qian west to look for allies against the Xiongnu nomads. He came back some 13 years later with news of the kingdoms of Central Asia. The Han set up fortified posts along the Gansu corridor as far as Dunhuang, and silk, lacquer and iron began to go west in exchange for horses, glass, silver and gold. Silk reached Rome through many middlemen: no merchant traveled the whole route.', src: ['hansen'] },

  /* from year 1 to 1450 */
  { id: 'teotihuacan', y: 250, y2: 550, k: 'peoples', place: 'Teotihuacan, Mexico', p: [-98.84, 19.69], t: 'Teotihuacan: good housing for everyone',
    txt: 'Teotihuacan, in the Valley of Mexico, had close to 100,000 inhabitants, with the Pyramids of the Sun and the Moon and a great avenue. Around 300 AD, the Temple of the Feathered Serpent, linked to human sacrifice, was burned. After that the city lived in some 2,000 stone apartment compounds, comfortable and similar to one another, built for almost the whole population. No one has found royal tombs or images of rulers. Graeber and Wengrow read this as a collective choice for a more equal government; other archaeologists think there may have been rulers who did not allow themselves to be portrayed.', src: ['cowgill', 'graeber'] },
  { id: 'maya', y: 250, y2: 900, k: 'government', place: 'Calakmul', p: [-89.74, 18.1], t: 'The Maya cities',
    txt: 'Between about 250 and 900, dozens of Maya cities, such as Tikal and Calakmul, were ruled by sacred kings who carved their deeds on stelae, in a script that can now largely be read. The Maya had precise calendars and used zero. The cities lived between wars and alliances: Tikal and Calakmul fought over the region for more than a century. In the 9th century, many southern cities were abandoned. Drought, war and worn-out soil are explanations that researchers combine in different ways.', src: ['martingrube'] },
  { id: 'fallofrome', y: 476, k: 'government', place: 'Ravenna', p: [12.2, 44.42], t: 'End of the Western Roman Empire',
    txt: 'In 476, the Germanic military leader Odoacer deposed the young emperor Romulus Augustulus at Ravenna and put no one in his place. The Western Empire had already broken up into Gothic, Frankish and Vandal kingdoms; the Eastern Empire, with its capital at Constantinople, lasted until 1453. The date is more a symbol than a break: for people living then, much stayed the same. Historians still debate whether it was a violent fall or a slow transformation.', src: ['wickham', 'wardperkins'] },
  { id: 'tangchangan', y: 618, y2: 907, k: 'economy', place: 'Chang\'an (Xi\'an)', p: [108.94, 34.26], t: 'Tang China and Chang\'an',
    txt: 'Under the Tang dynasty (618–907), Chang\'an was probably the largest city in the world, with about 1 million inhabitants, walls and a grid of streets. Sogdian, Persian, Arab and Korean merchants lived there, and there were Buddhist, Zoroastrian, Manichaean and Christian temples. Woodblock printing spread in Tang China: the oldest dated printed book, the Diamond Sutra, is from 868. The Japanese capital of Nara was laid out as a copy of Chang\'an.', src: ['lewis'] },
  { id: 'baghdad', y: 762, y2: 1258, k: 'ideas', place: 'Baghdad', p: [44.36, 33.31], t: 'Baghdad and the House of Wisdom',
    txt: 'Islam was born in Arabia in the early 7th century, with the Prophet Muhammad, and within a hundred years the caliphs ruled from the Iberian Peninsula to Central Asia. In 762, the Abbasid caliph al-Mansur founded Baghdad, a round city on the banks of the Tigris that soon became one of the largest in the world. There, translators put Greek, Persian and Indian works of medicine, astronomy and mathematics into Arabic, and al-Khwarizmi wrote the book that gave us the words algebra and algorithm. The Mongols sacked the city in 1258.', src: ['kennedy'] },
  { id: 'althing', y: 793, y2: 1066, k: 'peoples', place: 'Þingvellir, Iceland', p: [-21.12, 64.26], t: 'Vikings: raids, voyages and assemblies',
    txt: 'In 793, men from Scandinavia raided the monastery of Lindisfarne, in England. Over the next two centuries the Vikings raided, traded and settled from Ireland to Kyiv. Those who settled Iceland had no king: from 930, chiefs and free men met every summer at the Althing, at Þingvellir, to make laws and settle disputes. Around the year 1000, Icelanders and Greenlanders reached Newfoundland, in America, where they stayed only a short time. Iceland accepted a king, the king of Norway, only in 1262.', src: ['byock'] },
  { id: 'polynesia', y: 1000, y2: 1280, k: 'peoples', place: 'Society Islands (Tahiti)', p: [-149.43, -17.65], t: 'The Polynesian navigators',
    txt: 'In double canoes, steering by the stars, the waves and the birds, the Polynesians settled the last uninhabited islands of the Pacific. Setting out from the Society Islands, near Tahiti, they reached Hawaii, Rapa Nui and, around 1250–1300, New Zealand, the last large landmass on the planet to be settled. They carried pigs, chickens, yams and taro. The sweet potato, an American plant, was already in Polynesia before Columbus: a sign that they also reached South America.', src: ['kirch'] },
  { id: 'cahokia', y: 1050, y2: 1350, k: 'peoples', place: 'Cahokia, Mississippi', p: [-90.06, 38.66], t: 'Cahokia',
    txt: 'Around 1050, on the banks of the Mississippi, near present-day St. Louis, Cahokia suddenly grew to perhaps 15,000 inhabitants, with a huge plaza and more than a hundred earth mounds. The largest, Monks Mound, is 30 meters high. There were human sacrifices in elite burials and, later, a palisade around the center; by about 1350 the city was abandoned. Graeber and Wengrow suggest that the peoples of the region kept a bad memory of this experience and came to reject powerful rulers. It is a debated hypothesis.', src: ['pauketat', 'graeber'] },
  { id: 'zimbabwe', y: 1100, y2: 1450, k: 'economy', place: 'Great Zimbabwe', p: [30.93, -20.27], t: 'Great Zimbabwe',
    txt: 'On the plateau of present-day Zimbabwe, Shona-speaking peoples built granite walls without mortar between the 11th and 15th centuries, some of them 11 meters high. The city, which may have had more than 10,000 inhabitants, lived on cattle and on the trade in gold and ivory. These were carried to the Swahili ports of the Indian Ocean and exchanged for glass beads from India and Chinese porcelain. In the 19th century, white settlers claimed that Africans could not have built it; archaeologists showed the opposite.', src: ['pikirayi'] },
  { id: 'mongols', y: 1206, y2: 1368, k: 'conflict', place: 'Karakorum, Mongolia', p: [102.83, 47.2], t: 'The Mongol Empire',
    txt: 'In 1206, an assembly of steppe chiefs proclaimed Temujin as Genghis Khan. Within a few decades, the Mongol armies, on horseback, conquered or attacked lands from Korea to Hungary, in one of the largest empires in history, with massacres of whole cities. After the conquests, the routes of Asia became safer, and merchants, missionaries and Marco Polo traveled along them. Diseases traveled too: the plague that reached Europe in 1347 came along these roads.', src: ['weatherford'] },
  { id: 'mansamusa', y: 1324, k: 'economy', place: 'Timbuktu, Mali', p: [-3.0, 16.77], t: 'Mansa Musa goes to Mecca',
    txt: 'In 1324, Mansa Musa, king of Mali, crossed the Sahara on his way to Mecca with a retinue of thousands of people and a great deal of gold. In Cairo he gave away so much that, according to the chronicler al-Umari, the price of the metal fell for years. Mali controlled the gold mines of the upper Niger and Senegal, which supplied much of the Mediterranean. On his return, Musa brought scholars and architects, and Timbuktu became a center of Islamic learning. In 1375, the Catalan Atlas drew him on a throne, holding a gold nugget.', src: ['levtzion'] },
  { id: 'tenochtitlan', y: 1325, y2: 1521, k: 'government', place: 'Tenochtitlan', p: [-99.13, 19.43], t: 'Founding of Tenochtitlan',
    txt: 'According to tradition, in 1325 the Mexica founded Tenochtitlan on an island in Lake Texcoco, where they saw an eagle perched on a cactus. In less than two centuries the city grew to some 200,000 inhabitants. It was linked to the shore by causeways and surrounded by chinampas, garden beds built on the lake. With Texcoco and Tlacopan, it formed the Triple Alliance, which collected tribute from dozens of peoples in central Mexico. The eagle on the cactus is now on the flag of Mexico.', src: ['msmith'] },
  { id: 'blackdeath', y: 1347, y2: 1351, k: 'peoples', place: 'Messina, Sicily', p: [15.55, 38.19], t: 'The Black Death',
    txt: 'In October 1347, Genoese galleys coming from the Black Sea reached Messina, in Sicily, with the plague on board. The disease is caused by the bacterium Yersinia pestis and was spread by fleas, and perhaps also from person to person. In four years it killed between a third and half of all Europeans, as well as multitudes in Egypt and the Middle East. With fewer hands to work, the surviving laborers won better wages in many regions. There was also persecution: Jewish communities were massacred, accused of poisoning wells.', src: ['benedictow'] },
  { id: 'zhenghe', y: 1405, y2: 1433, k: 'economy', place: 'Malindi, East Africa', p: [40.12, -3.22], t: 'The fleets of Zheng He',
    txt: 'Between 1405 and 1433, Admiral Zheng He led seven voyages from Ming China across the Indian Ocean, with dozens of ships and almost 28,000 men on the first. The fleets called at Java, Ceylon, Calicut and Hormuz and reached the coast of East Africa; in 1415, envoys from Malindi brought a giraffe to the emperor. After 1433 the Ming court ended the voyages. Sixty-five years later, it was at Malindi that Vasco da Gama found a pilot to cross the Indian Ocean.', src: ['dreyer'] },
  { id: 'inca', y: 1438, y2: 1533, k: 'government', place: 'Cusco', p: [-71.97, -13.52], t: 'The Inca Empire',
    txt: 'Around 1438, according to the chronicles, Pachacuti defeated the Chanka and began to make Cusco the capital of an empire. In less than a hundred years, Tawantinsuyu stretched from present-day Ecuador to central Chile, with some 10 million people and almost 40,000 kilometers of roads. There were hardly any markets or money. Families owed labor in turns, the mita, and the state stored food and cloth in thousands of storehouses. Accounts were kept on quipus, knotted cords.', src: ['daltroy'] },

  /* 1450–1549 */
  { id: 'constantinople1453', y: 1453, k: 'conflict', place: 'Constantinople', p: [28.95, 41.02], t: 'The Ottomans take Constantinople',
    txt: 'On 29 May 1453, after a siege of almost two months, the Ottoman sultan Mehmed II took Constantinople, capital of what was left of the Byzantine Empire. Huge cannons, made by a founder named Orban, broke through walls that had held for a thousand years. The city became Istanbul, the Ottoman capital, and Hagia Sophia became a mosque. The Ottomans now controlled the passage between the Black Sea and the Mediterranean.', src: ['crowley'] },
  { id: 'gutenbergpress', y: 1455, k: 'ideas', place: 'Mainz', p: [8.27, 50.0], t: 'Gutenberg’s press',
    txt: 'In Mainz, in Germany, Johannes Gutenberg combined movable metal type, an oil-based ink and a press adapted from wine presses. Around 1455 the Gutenberg Bible was finished, in some 180 copies. By 1500 there were print shops in more than 250 European cities and millions of printed books. Movable type already existed in China and Korea, but there, with thousands of characters, woodblock printing remained more practical.', src: ['eisenstein'] },
  { id: 'columbus1492', y: 1492, k: 'government', place: 'Guanahani, Bahamas', p: [-74.5, 24.1], t: 'Columbus reaches the Caribbean',
    txt: 'On 12 October 1492, three ships paid for by the monarchs of Castile and commanded by the Genoese Christopher Columbus reached an island in the Bahamas that the Taíno called Guanahani. Columbus was looking for Asia and never admitted he had found a new continent. The Taíno of Hispaniola were forced to work in the gold mines, and between violence and epidemics, a few decades later almost none were left. The voyage led Portugal and Castile to negotiate the Treaty of Tordesillas two years later.', src: ['armesto'] },
  { id: 'luther1517', y: 1517, k: 'ideas', place: 'Wittenberg', p: [12.65, 51.87], t: 'Luther and the Reformation',
    txt: 'In 1517, the monk Martin Luther made public in Wittenberg 95 theses against the sale of indulgences, the forgiveness of sins sold by the Church. Thanks to the printing press, his pamphlets spread across Germany in weeks. Western Christendom split between Catholics and Protestants, and religious wars followed that dragged on until 1648. The Catholic Church answered with the Council of Trent and backed new orders, such as the Jesuits, who would reach Brazil in 1549.', src: ['roper'] },
  { id: 'tlaxcala', y: 1519, k: 'peoples', place: 'Tlaxcala', p: [-98.24, 19.32], t: 'The council of Tlaxcala',
    txt: 'Tlaxcala, east of the Valley of Mexico, was never conquered by the Mexica. It was governed by a council of leaders, and anyone who wanted to join it went through fasts, trials and public humiliation. When Cortés arrived in 1519, the Tlaxcalans first fought him. Then the council debated and decided to ally with the Spaniards against Tenochtitlan. Graeber and Wengrow count Tlaxcala among the Indigenous urban republics. How the council worked is known mainly from Spanish chroniclers, and the details are debated.', src: ['fargher', 'graeber'] },
  { id: 'cortes', y: 1521, k: 'conflict', place: 'Tenochtitlan', p: [-99.13, 19.43], t: 'The fall of Tenochtitlan',
    txt: 'In August 1521, after a siege of almost three months, Tenochtitlan fell. It fell to a few hundred Spaniards led by Hernán Cortés and to tens of thousands of warriors from Tlaxcala and other peoples who wanted to be free of Mexica rule. A smallpox epidemic that arrived in 1520 had already killed many people in the city, including the ruler Cuitláhuac. On the ruins the Spaniards built Mexico City, capital of New Spain. The conquest was largely a war between Indigenous peoples, and the Spaniards kept the result.', src: ['restall'] },
  { id: 'pizarro', y: 1532, y2: 1572, k: 'conflict', place: 'Cajamarca', p: [-78.52, -7.16], t: 'Pizarro captures Atahualpa',
    txt: 'In November 1532, at Cajamarca, Francisco Pizarro and fewer than 200 Spaniards ambushed and captured the Inca Atahualpa, who had just defeated his brother Huáscar in a civil war. Atahualpa paid a ransom of one room full of gold and two of silver and was executed anyway, in 1533. Smallpox had reached the Andes before the Spaniards and killed the previous Inca, Huayna Capac. Inca resistance continued at Vilcabamba until 1572.', src: ['hemmingincas'] },
  { id: 'potosi', y: 1545, y2: 1650, k: 'economy', place: 'Potosí', p: [-65.75, -19.58], t: 'The silver of Potosí',
    txt: 'In 1545 the Spaniards found a mountain of silver at Potosí, in the Andes, more than 4,000 meters above sea level. Under the mita, the labor-turn system inherited from the Incas and reshaped by the Spaniards, thousands of Indigenous people were forced down into the mines, where many died. Around 1600, Potosí had some 150,000 inhabitants, as many as the largest cities in Europe. Its silver paid for Spain’s wars and ended up in China, which collected taxes in silver.', src: ['bakewell', 'flynn'] },

  /* 1549–1693 */
  { id: 'manila', y: 1571, y2: 1815, k: 'economy', place: 'Manila', p: [120.97, 14.59], t: 'The Manila galleon',
    txt: 'In 1571 the Spaniards founded Manila, in the Philippines, and began sending one or two galleons every year across the Pacific to Acapulco, in Mexico. They sailed with silk, porcelain and spices brought by Chinese merchants and came back with American silver. For the first time, every inhabited continent was linked by regular trade routes. The line lasted until 1815.', src: ['flynn'] },
  { id: 'vocamsterdam', y: 1602, k: 'economy', place: 'Amsterdam', p: [4.9, 52.37], t: 'The Dutch East India Company',
    txt: 'In 1602, Dutch merchants founded the VOC, the East India Company, with a monopoly on Dutch trade in Asia and the right to make war, treaties and forts. Its shares were bought and sold on the Amsterdam exchange, one of the first in the world. The VOC took Malacca, Ceylon and other ports from the Portuguese, and in 1619 it founded Batavia, today’s Jakarta. In 1621, the same model gave rise to the West India Company, which would attack Brazil.', src: ['boxerdutch'] },
  { id: 'westphalia', y: 1648, k: 'government', place: 'Münster', p: [7.63, 51.96], t: 'The Peace of Westphalia',
    txt: 'In 1648, treaties signed at Münster and Osnabrück ended the Thirty Years’ War, which had devastated central Europe and killed perhaps a third of the population in parts of Germany. The peace confirmed that each prince decided the official religion of his territory, and Spain recognized the independence of the United Provinces, the Netherlands. It is often named as the beginning of a system of sovereign states, though many historians say that reading came later.', src: ['wilson'] },
  { id: 'gloriousrev', y: 1688, y2: 1689, k: 'government', place: 'Torbay, England', p: [-3.52, 50.45], t: 'The Glorious Revolution',
    txt: 'In November 1688, the Dutchman William of Orange landed at Torbay, in southern England, with a fleet of more than 400 ships, and the Catholic king James II fled to France. In 1689, Parliament gave the crown to William and his wife, Mary, and passed the Bill of Rights. The king could no longer suspend laws, levy taxes or keep an army without Parliament. Some economists link this change to English growth and to the Industrial Revolution; the link is debated.', src: ['pincus'] },

  /* 1693–1807 */
  { id: 'kandiaronk', y: 1701, k: 'ideas', place: 'Montreal', p: [-73.57, 45.5], t: 'Kandiaronk and the Indigenous critique',
    txt: 'Kandiaronk, a Wendat (Huron) chief and great orator, helped negotiate the Great Peace of Montreal, signed in August 1701 between New France and about 40 Indigenous peoples, and died during the conference. Years before, he had talked at length with the Baron de Lahontan. In 1703 Lahontan published dialogues with an Indigenous man called Adario, modeled on him, who criticizes the money, inequality, punishments and obedience of Europeans. Graeber and Wengrow argue that this Indigenous critique weighed on the European debate about freedom and inequality; many historians see Adario as a character invented by Lahontan.', src: ['havard', 'lahontan', 'graeber'] },
  { id: 'rousseau', y: 1755, k: 'ideas', place: 'Dijon', p: [5.04, 47.32], t: 'Rousseau and the origin of inequality',
    txt: 'In 1753, the Academy of Dijon opened an essay contest on the origin of inequality among men. Jean-Jacques Rousseau answered with a discourse, published in 1755. In the beginning, he wrote, humans lived free and equal, and inequality came with ownership of land and with farming. The text did not win the prize, but it became one of the most repeated stories about the human past. The Dawn of Everything begins precisely by challenging that story.', src: ['rousseau', 'graeber'] },
  { id: 'plassey', y: 1757, k: 'conflict', place: 'Plassey, Bengal', p: [88.25, 23.8], t: 'The Battle of Plassey',
    txt: 'On 23 June 1757, troops of the British East India Company, led by Robert Clive, defeated the nawab of Bengal at Plassey, after one of his generals, Mir Jafar, was bought off and did not fight. In 1765 the Company won the right to collect the taxes of Bengal, the richest province of India. It was the start of almost two centuries of British rule on the subcontinent. Indian cotton cloth, which Europe bought, was eventually overtaken by cloth from Manchester.', src: ['dalrymple'] },
  { id: 'tupacamaru', y: 1780, y2: 1781, k: 'conflict', place: 'Tinta, near Cusco', p: [-71.4, -14.15], t: 'The rebellion of Túpac Amaru II',
    txt: 'In November 1780, José Gabriel Condorcanqui, an Indigenous chief descended from the Incas who took the name Túpac Amaru II, arrested and executed a Spanish district governor (corregidor) at Tinta, near Cusco. The revolt, against new taxes, the mita and the abuses of officials, spread through the Andes to Upper Peru, where Túpac Katari besieged La Paz. Túpac Amaru was captured and quartered in Cusco in 1781, and tens of thousands of people died on both sides.', src: ['walker'] },

  /* 1807–1822 */
  { id: 'abolition1807', y: 1807, k: 'government', place: 'London', p: [-0.13, 51.5], t: 'Britain bans the slave trade',
    txt: 'After 20 years of campaigning, with petitions, a sugar boycott and books by formerly enslaved people such as Olaudah Equiano, the British Parliament banned the trade in Africans on British ships in 1807. Slavery in the British colonies was abolished only in 1833. The British navy began hunting slave ships and pressing Portugal and Brazil, which kept up the trade for more than 40 years. How much morality, politics and economic interest weighed in this turn has been debated since Eric Williams published Capitalism and Slavery in 1944.', src: ['williams', 'brown'] },
  { id: 'hidalgo', y: 1810, y2: 1821, k: 'conflict', place: 'Dolores, Mexico', p: [-100.93, 21.16], t: 'The Cry of Dolores',
    txt: 'On 16 September 1810, the priest Miguel Hidalgo rang the church bell at Dolores and called on his flock, largely Indigenous people and poor mestizos, to rise against Spanish rule. The revolt became a war that killed tens of thousands. Hidalgo was shot in 1811, and José María Morelos carried on the fight, with the end of slavery and of Indigenous tribute in his program. Mexico became independent only in 1821, in a deal between the military and the elites.', src: ['vanyoung'] },
  { id: 'bolivar', y: 1819, y2: 1824, k: 'conflict', place: 'Boyacá', p: [-73.4, 5.45], t: 'Bolívar and the independence of the Andes',
    txt: 'In 1816, a defeated Simón Bolívar received weapons and men in Haiti from President Alexandre Pétion, who asked in return for the end of slavery in the lands he freed. In August 1819, after crossing the Andes, Bolívar defeated the Spaniards at the Boyacá bridge and entered Bogotá. Gran Colombia was born; in 1830 it would split into Venezuela, Colombia and Ecuador. With Sucre’s victory at Ayacucho in 1824, Spanish rule in South America came to an end.', src: ['lynch'] },

  /* 1822–1889 */
  { id: 'opium', y: 1839, y2: 1842, k: 'conflict', place: 'Canton', p: [113.26, 23.13], t: 'The Opium War',
    txt: 'To pay for the tea they bought from China, British traders sold opium grown in India there. In 1839, the imperial commissioner Lin Zexu seized and destroyed more than a thousand tonnes of opium near Canton, and Britain answered with a war. Steamships and modern cannons beat the Chinese defenses, and the Treaty of Nanjing, in 1842, opened five ports to the British and handed them Hong Kong. In China, this is where the so-called "century of humiliation" begins.', src: ['platt'] },
  { id: 'spring1848', y: 1848, k: 'ideas', place: 'Paris', p: [2.36, 48.85], t: 'The revolutions of 1848',
    txt: 'In February 1848, a revolt in Paris overthrew King Louis-Philippe and proclaimed a republic. Within weeks, uprisings spread to Vienna, Berlin, Milan and Budapest. In the same month, Karl Marx and Friedrich Engels published the Communist Manifesto in London. In April, the new French government abolished slavery in the colonies and adopted the vote for all adult men. Almost all the revolutions were defeated in little more than a year, but their ideas of nation, democracy and socialism shaped the rest of the century.', src: ['hobsbawmcapital'] },
  { id: 'taiping', y: 1850, y2: 1864, k: 'conflict', place: 'Nanjing', p: [118.78, 32.06], t: 'The Taiping Rebellion',
    txt: 'Hong Xiuquan, a man who had failed the imperial exams and claimed to be the younger brother of Jesus, led a movement against the Qing dynasty in southern China. In 1853 his followers took Nanjing and founded the Heavenly Kingdom of Great Peace, which promised land shared out equally and banned opium and foot-binding. The war lasted until 1864 and killed between 20 and 30 million people, the deadliest of the 19th century. The dynasty survived, but greatly weakened.', src: ['platttaiping'] },
  { id: 'berlin1884', y: 1884, y2: 1885, k: 'government', place: 'Berlin', p: [13.38, 52.51], t: 'The Berlin Conference',
    txt: 'Between November 1884 and February 1885, representatives of 14 countries, almost all European, met in Berlin to agree on rules for occupying the African coast and for trade on the Congo and Niger rivers. No African was invited. The conference did not carve up the map of Africa, but it sped up the race: by 1914, only Ethiopia and Liberia were not under European rule. Many of the borders drawn at that time are still there.', src: ['pakenham'] },
  { id: 'congofreestate', y: 1885, y2: 1908, k: 'economy', place: 'Congo Basin', p: [18.26, 0.05], t: 'Leopold II’s Congo rubber',
    txt: 'The Berlin Conference recognized the Congo Free State as the personal property of King Leopold II of Belgium. To meet the demand for rubber, his agents forced villages to deliver quotas, took women hostage and cut off the hands of those who fell short. The population fell sharply, through violence, hunger and disease, in numbers still debated. Reports by the British consul Roger Casement, by missionaries and by journalists led Belgium to take the Congo away from the king in 1908. Casement later investigated similar abuses on the rubber estates of the Putumayo, in the Amazon.', src: ['hochschild'] },

  /* 1889–1930 */
  { id: 'adwa', y: 1896, k: 'conflict', place: 'Adwa, Ethiopia', p: [38.9, 14.17], t: 'The Battle of Adwa',
    txt: 'On 1 March 1896, the army of the Ethiopian emperor Menelik II, with more than 100,000 men and modern weapons bought in Europe, defeated an Italian force of about 17,000 at Adwa. Italy had to recognize Ethiopia’s independence. It was the greatest defeat of a European army in Africa in that period, and it became a symbol for anticolonial and Black movements around the world.', src: ['jonas'] },
  { id: 'mexico1910', y: 1910, y2: 1920, k: 'conflict', place: 'Morelos, Mexico', p: [-99.2, 18.75], t: 'The Mexican Revolution',
    txt: 'In 1910, the revolt against Porfirio Díaz, in power for more than 30 years, opened a decade of wars in Mexico that killed perhaps a million people. In Morelos, Emiliano Zapata’s peasants took back land from the sugar estates under the slogan "land and liberty". The Constitution of 1917 guaranteed land reform and communal lands, the ejidos. Zapata was murdered in 1919 and became a symbol of the peasant and Indigenous struggle.', src: ['womack'] },
  { id: 'ww1', y: 1914, y2: 1918, k: 'conflict', place: 'Somme, France', p: [2.7, 50.0], t: 'The First World War',
    txt: 'In 1914, the murder of the heir to the Austrian throne in Sarajevo drew the great European empires and their colonies into war. On the Western Front, the armies spent years stuck in trenches. The Battle of the Somme alone, in 1916, left more than a million dead and wounded, and some 10 million soldiers died in the whole war. Brazil declared war on Germany in 1917, after Brazilian ships were sunk, and sent a naval division and a medical mission. The war brought down the Russian, German, Austro-Hungarian and Ottoman empires.', src: ['hobsbawm'] },
  { id: 'russianrev1917', y: 1917, k: 'ideas', place: 'Petrograd', p: [30.3, 59.94], t: 'The Russian Revolution',
    txt: 'In February 1917, strikes and mutinies in Petrograd overthrew Tsar Nicholas II. In October, Lenin’s Bolsheviks took power in the name of the soviets, the councils of workers and soldiers, and pulled Russia out of the war. After a civil war, the Soviet Union was born in 1922, with a single party. The revolution inspired communist parties around the world, such as Brazil’s, founded in 1922.', src: ['fitzpatrick'] },

  /* 1930–1964 */
  { id: 'saltmarch', y: 1930, k: 'ideas', place: 'Dandi, India', p: [72.8, 20.89], t: 'Gandhi and the Salt March',
    txt: 'In March 1930, Mohandas Gandhi set out on foot from Ahmedabad with 78 followers. After 24 days and some 385 kilometers, he reached the beach at Dandi and picked up a handful of salt: making salt was a monopoly of the British government. Thousands across the country did the same, and more than 60,000 people were arrested. Nonviolent civil disobedience became the method of India’s independence movement and later inspired the civil rights movement in the United States.', src: ['guha'] },
  { id: 'ww2', y: 1939, y2: 1945, k: 'conflict', place: 'Gdańsk (Danzig)', p: [18.65, 54.4], t: 'The Second World War',
    txt: 'On 1 September 1939, Nazi Germany invaded Poland, and the war spread across Europe, North Africa and, with Japan, Asia and the Pacific. It was the deadliest war in history: between 70 and 85 million dead, most of them civilians, some 27 million in the Soviet Union alone. Brazil entered in 1942, after German submarines sank Brazilian ships, and sent the FEB, the Brazilian Expeditionary Force, to Italy in 1944. The war ended in 1945, with the defeat of Germany in May and of Japan in August.', src: ['beevor', 'hobsbawm'] },
  { id: 'holocaust', y: 1941, y2: 1946, k: 'ideas', place: 'Nuremberg', p: [11.08, 49.45], t: 'The Holocaust and the Nuremberg trials',
    txt: 'Between 1941 and 1945, Nazi Germany and its allies killed about 6 million Jews, in mass shootings and in extermination camps such as Auschwitz, in occupied Poland. They also killed Roma and Sinti, disabled people, Soviet prisoners and opponents. In November 1945, an Allied tribunal began trying the main Nazi leaders at Nuremberg for crimes against humanity, a new idea in law. In 1948, the UN approved the convention against genocide, a word coined by the jurist Raphael Lemkin in 1944.', src: ['friedlander'] },
  { id: 'hiroshima1945', y: 1945, k: 'conflict', place: 'Hiroshima', p: [132.45, 34.39], t: 'The bombs on Hiroshima and Nagasaki',
    txt: 'On 6 August 1945, an American plane dropped on Hiroshima the first atomic bomb used in war; three days later, another destroyed Nagasaki. By the end of that year, the two bombs had killed more than 150,000 people, perhaps close to 250,000, almost all civilians. Japan announced its surrender on 15 August. Whether the bombs were needed to end the war is still debated; what is certain is that they opened the age of nuclear weapons.', src: ['hasegawa'] },
  { id: 'un', y: 1945, k: 'government', place: 'San Francisco', p: [-122.42, 37.78], t: 'The founding of the UN',
    txt: 'In June 1945, delegates from 50 countries signed the Charter of the United Nations in San Francisco, to keep the peace that the League of Nations had failed to secure. The five great victors of the war got permanent seats and veto power on the Security Council. Brazil was one of the founding members and, by tradition, gives the first speech of the General Assembly’s annual debate. In 1948, the Assembly approved the Universal Declaration of Human Rights in Paris.', src: ['mazower'] },
  { id: 'india1947', y: 1947, k: 'government', place: 'New Delhi', p: [77.21, 28.61], t: 'Independence and partition of India',
    txt: 'On 15 August 1947, British India became independent, split into two countries: India, with a Hindu majority, and Pakistan, with a Muslim majority. The partition, drawn in haste, caused one of the largest migrations in history, with some 15 million people crossing the new borders. Massacres killed from hundreds of thousands to perhaps 2 million people, depending on the estimate. Gandhi was murdered by a Hindu nationalist in January 1948. India’s independence encouraged anticolonial struggles in Asia and Africa.', src: ['ykhan'] },
  { id: 'coldwar', y: 1947, y2: 1991, k: 'conflict', place: 'Washington', p: [-77.04, 38.9], t: 'The Cold War',
    txt: 'In March 1947, President Harry Truman promised help to any country threatened by communism, and the world split into two blocs, led by the United States and the Soviet Union. The two powers never fought each other directly. But they ran a nuclear arms race and backed wars, coups and guerrillas from Korea to Vietnam and from Angola to Latin America. In Brazil and its neighbors, anticommunism served as a justification for military coups. The Cold War ended with the end of the Soviet Union in 1991.', src: ['westad'] },
  { id: 'china1949', y: 1949, k: 'ideas', place: 'Beijing', p: [116.39, 39.9], t: 'The Chinese Revolution',
    txt: 'On 1 October 1949, after more than 20 years of civil war and the Japanese invasion, Mao Zedong proclaimed the People’s Republic of China in Beijing. The communists won with the support of the peasants, to whom they promised land. In the land reform that followed, hundreds of thousands of landowners were killed, perhaps more than a million. The Great Leap Forward, from 1958 to 1962, caused a famine that killed tens of millions. China became the most populous country in the world under a one-party regime.', src: ['spence'] },
  { id: 'decolonization1960', y: 1960, k: 'government', place: 'Léopoldville (Kinshasa)', p: [15.31, -4.32], t: 'The Year of Africa',
    txt: 'In 1960, 17 African countries became independent, among them Nigeria, Senegal, Somalia, Madagascar and the Congo. At the Congo’s independence ceremony on 30 June, Prime Minister Patrice Lumumba recalled the humiliations of colonial rule in front of the Belgian king. Months later he was overthrown and, in January 1961, murdered with Belgian involvement, in a case that also involved the CIA. The Portuguese colonies, such as Angola and Mozambique, became independent only in 1975, after long wars.', src: ['meredith'] },
  { id: 'missiles1962', y: 1962, k: 'conflict', place: 'San Cristóbal, Cuba', p: [-82.9, 22.8], t: 'The Cuban Missile Crisis',
    txt: 'In October 1962, American spy planes photographed sites in Cuba for Soviet nuclear missiles able to reach the United States. For 13 days, with the American navy blockading the island, the world came close to nuclear war. Kennedy and Khrushchev reached a deal: the Soviets withdrew the missiles, and the Americans promised not to invade Cuba and secretly removed their own missiles from Turkey. Afterwards, the two powers set up a direct line of communication.', src: ['fursenko'] },

  /* 1964–2000 */
  { id: 'chile1973', y: 1973, y2: 1990, k: 'conflict', place: 'Santiago, Chile', p: [-70.65, -33.45], t: 'The coup in Chile',
    txt: 'On 11 September 1973, the Chilean military bombed the La Moneda palace, and the socialist president Salvador Allende, elected in 1970, died inside. General Augusto Pinochet ruled until 1990. More than 3,000 people were killed or disappeared, and tens of thousands were imprisoned and tortured. The United States government had worked against Allende since his election, and the Brazilian dictatorship supported the coup. In 1975, the dictatorships of the Southern Cone created Operation Condor to hunt opponents across borders.', src: ['harmer'] },
  { id: 'oil1973', y: 1973, k: 'economy', place: 'Kuwait', p: [47.98, 29.37], t: 'The oil shock',
    txt: 'In October 1973, during the war between Israel and Arab countries, the Arab oil producers, meeting in Kuwait, cut production and placed an embargo on the United States and the Netherlands. Within a few months the price of a barrel quadrupled. Brazil, which imported most of the oil it used, saw the end of its "economic miracle" and began borrowing to keep growing. To depend less on oil, the government created Proálcool in 1975, a program that put sugarcane ethanol in cars.', src: ['yergin'] },
  { id: 'berlinwallfall', y: 1989, y2: 1991, k: 'ideas', place: 'Berlin', p: [13.38, 52.52], t: 'The fall of the Berlin Wall',
    txt: 'On the night of 9 November 1989, after weeks of protests in East Germany, a spokesman announced by mistake that the border was open, and thousands of Berliners crossed the Wall. That year the communist regimes fell one by one in Poland, Hungary, Czechoslovakia, Bulgaria and Romania. Germany reunified in October 1990, and the Soviet Union ceased to exist in December 1991.', src: ['sarotte'] },
  { id: 'apartheid', y: 1990, y2: 1994, k: 'ideas', place: 'Cape Town', p: [18.42, -33.92], t: 'The end of apartheid',
    txt: 'From 1948, apartheid separated white, Black, mixed-race and Indian people in South Africa by law, with different neighborhoods, schools and jobs, and denied the vote to the Black majority. After decades of resistance, strikes and international sanctions, the government freed Nelson Mandela on 11 February 1990, after 27 years in prison. In April 1994, in the first election in which everyone could vote, Mandela was elected president.', src: ['lthompson'] },
  { id: 'zapatistas', y: 1994, k: 'peoples', place: 'Chiapas, Mexico', p: [-92.64, 16.74], t: 'The Zapatistas of Chiapas',
    txt: 'On 1 January 1994, the day the North American Free Trade Agreement came into force, the Zapatista Army of National Liberation, made up mostly of Indigenous Maya, occupied towns in Chiapas, in southern Mexico. A ceasefire came twelve days later. Since then, Zapatista communities have run their own schools, clinics and governments, with rotating posts and assemblies, without depending on the Mexican state. They are one of the present-day cases of autonomy cited in debates about alternatives to the state.', src: ['nharvey'] }
];

